// Standalone Offline Markdown Parser
(function (global) {
  'use strict';

  function escapeHtml(str) {
    return str
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  function parseMarkdown(md) {
    if (!md) return '';

    // Strip YAML frontmatter if present
    md = md.replace(/^---[\s\S]*?---\r?\n/, '');

    // Normalize newlines
    md = md.replace(/\r\n/g, '\n').replace(/\r/g, '\n');

    const lines = md.split('\n');
    let html = '';
    let inCodeBlock = false;
    let codeLanguage = '';
    let codeContent = [];
    let inList = false;
    let listType = null; // 'ul' or 'ol'
    let inBlockquote = false;
    let blockquoteLines = [];
    let inTable = false;
    let tableLines = [];

    function closeList() {
      if (inList) {
        html += `</${listType}>\n`;
        inList = false;
        listType = null;
      }
    }

    function closeBlockquote() {
      if (inBlockquote) {
        html += `<blockquote>\n${parseMarkdown(blockquoteLines.join('\n'))}\n</blockquote>\n`;
        inBlockquote = false;
        blockquoteLines = [];
      }
    }

    function closeTable() {
      if (inTable) {
        html += renderTable(tableLines) + '\n';
        inTable = false;
        tableLines = [];
      }
    }

    function renderTable(lines) {
      if (lines.length < 2) return '';
      const headerLine = lines[0];
      const alignLine = lines[1];
      const dataLines = lines.slice(2);

      const splitRow = (row) => row.trim().replace(/^\||\|$/g, '').split('|').map(s => s.trim());

      const headers = splitRow(headerLine);
      const aligns = splitRow(alignLine).map(a => {
        if (/^:.*:$/.test(a)) return 'center';
        if (/^:/.test(a)) return 'left';
        if (/:$/.test(a)) return 'right';
        return 'left';
      });

      let res = '<div class="table-container"><table><thead><tr>';
      headers.forEach((h, i) => {
        const align = aligns[i] || 'left';
        res += `<th style="text-align:${align}">${parseInline(h)}</th>`;
      });
      res += '</tr></thead><tbody>';

      for (const row of dataLines) {
        const cells = splitRow(row);
        res += '<tr>';
        headers.forEach((_, i) => {
          const val = cells[i] || '';
          const align = aligns[i] || 'left';
          res += `<td style="text-align:${align}">${parseInline(val)}</td>`;
        });
        res += '</tr>';
      }
      res += '</tbody></table></div>';
      return res;
    }

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];

      // Code blocks
      if (line.trim().startsWith('```')) {
        if (!inCodeBlock) {
          closeList();
          closeBlockquote();
          closeTable();
          inCodeBlock = true;
          codeLanguage = line.trim().slice(3).trim();
          codeContent = [];
          continue;
        } else {
          inCodeBlock = false;
          const escapedCode = escapeHtml(codeContent.join('\n'));
          const langLabel = codeLanguage ? `<span class="code-lang">${codeLanguage}</span>` : '';
          html += `<div class="code-block-wrapper">${langLabel}<pre><code class="language-${codeLanguage}">${escapedCode}</code></pre></div>\n`;
          continue;
        }
      }

      if (inCodeBlock) {
        codeContent.push(line);
        continue;
      }

      // Tables
      if (line.trim().startsWith('|') && line.includes('|')) {
        closeList();
        closeBlockquote();
        inTable = true;
        tableLines.push(line);
        continue;
      } else if (inTable) {
        closeTable();
      }

      // Blockquote
      if (line.trim().startsWith('>')) {
        closeList();
        closeTable();
        inBlockquote = true;
        blockquoteLines.push(line.replace(/^\s*>\s?/, ''));
        continue;
      } else if (inBlockquote) {
        if (line.trim() === '') {
          closeBlockquote();
          continue;
        } else {
          blockquoteLines.push(line);
          continue;
        }
      }

      // Empty line
      if (line.trim() === '') {
        closeList();
        closeBlockquote();
        closeTable();
        continue;
      }

      // Horizontal rule
      if (/^(\*{3,}|-{3,}|_{3,})$/.test(line.trim())) {
        closeList();
        html += '<hr />\n';
        continue;
      }

      // Headings
      const headingMatch = line.match(/^(#{1,6})\s+(.*)$/);
      if (headingMatch) {
        closeList();
        const level = headingMatch[1].length;
        const text = headingMatch[2].trim();
        const slug = text.toLowerCase().replace(/[^a-z0-9_-]/g, '-').replace(/-+/g, '-');
        html += `<h${level} id="${slug}">${parseInline(text)}</h${level}>\n`;
        continue;
      }

      // Task list item: - [ ] or - [x]
      const taskMatch = line.match(/^(\s*)[-*+]\s+\[([ xX])\]\s+(.*)$/);
      if (taskMatch) {
        if (!inList || listType !== 'ul') {
          closeList();
          inList = true;
          listType = 'ul';
          html += '<ul class="task-list">\n';
        }
        const checked = taskMatch[2].toLowerCase() === 'x' ? 'checked disabled' : 'disabled';
        const itemText = parseInline(taskMatch[3]);
        html += `<li class="task-list-item"><input type="checkbox" ${checked} /> <span>${itemText}</span></li>\n`;
        continue;
      }

      // Unordered list: *, -, +
      const ulMatch = line.match(/^(\s*)[-*+]\s+(.*)$/);
      if (ulMatch) {
        if (!inList || listType !== 'ul') {
          closeList();
          inList = true;
          listType = 'ul';
          html += '<ul>\n';
        }
        html += `<li>${parseInline(ulMatch[2])}</li>\n`;
        continue;
      }

      // Ordered list: 1.
      const olMatch = line.match(/^(\s*)\d+\.\s+(.*)$/);
      if (olMatch) {
        if (!inList || listType !== 'ol') {
          closeList();
          inList = true;
          listType = 'ol';
          html += '<ol>\n';
        }
        html += `<li>${parseInline(olMatch[2])}</li>\n`;
        continue;
      }

      // Regular paragraph
      closeList();
      html += `<p>${parseInline(line)}</p>\n`;
    }

    closeList();
    closeBlockquote();
    closeTable();

    return html;
  }

  function parseInline(text) {
    if (!text) return '';

    // Images: ![alt](url)
    text = text.replace(/!\[(.*?)\]\((.*?)\)/g, '<img src="$2" alt="$1" class="md-image" />');

    // Links: [text](url)
    text = text.replace(/\[(.*?)\]\((.*?)\)/g, '<a href="$2" target="_blank" rel="noopener noreferrer">$1</a>');

    // Bold + Italic: ***text*** or ___text___
    text = text.replace(/(\*\*\*|___)(.*?)\1/g, '<strong><em>$2</em></strong>');

    // Bold: **text** or __text__
    text = text.replace(/(\*\*|__)(.*?)\1/g, '<strong>$2</strong>');

    // Italic: *text* or _text_
    text = text.replace(/(\*|_)(.*?)\1/g, '<em>$2</em>');

    // Strikethrough: ~~text~~
    text = text.replace(/~~(.*?)~~/g, '<del>$1</del>');

    // Inline Code: `code`
    text = text.replace(/`([^`]+)`/g, (match, code) => `<code>${escapeHtml(code)}</code>`);

    // Hashtags: #tag (click to filter)
    text = text.replace(/(?:^|\s)#([a-zA-Z0-9_\-\u00C0-\u024F]+)(?=$|\s|[.,;:!?])/g, (match, tag) => {
      return ` <span class="md-hashtag" onclick="window.filterByTag('${tag.toLowerCase()}'); event.stopPropagation();">#${tag}</span>`;
    });

    return text;
  }

  global.marked = {
    parse: parseMarkdown
  };

})(typeof window !== 'undefined' ? window : global);
